/// Parse the probe script's output.
///
/// KEY-PREFIXED, not positional, and that is the whole point. The first version echoed three bare
/// lines and read them by index — but [`super::ssh`] trims the whole output, so an empty first field (a
/// device with nothing deployed yet, which is every device the first time) collapsed the leading
/// newline and shifted every field up by one. `lumpy-space` duly reported its ARCHITECTURE as the
/// binary it was running, and read as unreachable because the arch line had been consumed.
/// A key prefix cannot shift.
pub fn parse_state(out: &str) -> crate::plan::RemoteState {
    let get = |k: &str| -> Option<String> {
        out.lines()
            .find_map(|l| l.trim().strip_prefix(k))
            .map(str::to_string)
            .filter(|v| !v.is_empty())
    };
    crate::plan::RemoteState {
        current_sha: get("cur="),
        previous_sha: get("prev="),
        arch: get("arch="),
    }
}
